#!/bin/bash
set -euxo pipefail
cd /gt/_work/src
# Build a tiny fuzzer-engine driver (main reading file) since gcc lacks -fsanitize=fuzzer
cat > /tmp/fuzz_driver.c <<'EOF'
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);
int main(int argc, char **argv)
{
    if (argc < 2) { fprintf(stderr, "usage: %s <input-file>\n", argv[0]); return 2; }
    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 2; }
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *buf = malloc(n > 0 ? (size_t)n : 1);
    if (n > 0 && fread(buf, 1, (size_t)n, f) != (size_t)n) { perror("fread"); return 2; }
    fclose(f);
    LLVMFuzzerTestOneInput(buf, (size_t)n);
    free(buf);
    return 0;
}
EOF
gcc -c -fsanitize=address -g -O1 -o /tmp/fuzz_driver.o /tmp/fuzz_driver.c
ar rcs /tmp/libfuzzengine.a /tmp/fuzz_driver.o

rm -rf build
mkdir build && cd build
export CC=gcc CXX=g++
export CFLAGS="-fsanitize=address -g -O1 -fno-omit-frame-pointer"
export CXXFLAGS="-fsanitize=address -g -O1 -fno-omit-frame-pointer"
export LIB_FUZZING_ENGINE="/tmp/libfuzzengine.a"
cmake -GNinja \
  -DCMAKE_C_FLAGS="$CFLAGS" \
  -DCMAKE_CXX_FLAGS="$CXXFLAGS" \
  -DBUILD_TESTING=OFF \
  -DOT_BUILD_EXECUTABLES=OFF \
  -DOT_FUZZ_TARGETS=ON \
  -DOT_MTD=OFF \
  -DOT_PLATFORM=external \
  -DOT_RCP=OFF \
  -DOT_DNS_CLIENT=ON \
  -DOT_COAP=ON \
  -DOT_COAPS=ON \
  -DOT_IP6_FRAGM=ON \
  -DOT_THREAD_VERSION=1.3 \
  ..
ninja ot-cli-received-fuzzer

